<?php declare(strict_types=1);use FastWebsite\Core\View;$value=static fn(string$f):string=>(string)($values[$f]??'');$editing=is_int($projectId);$published=$editing&&$currentStatus==='published';$action=$editing?$baseUrl.'admin/research/projects/'.$projectId:$baseUrl.'admin/research/projects';?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=$published?'Live project':($editing?'Project revision':'New research project')?></p><h1><?=$editing?'Edit project':'Create project'?></h1><p><?=$published?'The public project page stays online while you edit.':'Add the core project information and publish when ready.'?></p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/projects<?=$editing?'/'.$projectId:''?>">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><strong>Please correct the following:</strong><ul><?php foreach($errors as$error):?><li><?=View::escape($error)?></li><?php endforeach;?></ul></div><?php endif;?><?php if($published):?><div class="success-alert live-edit-notice"><strong>Editing published content.</strong> Saved changes apply immediately.</div><?php endif;?>
<form class="content-form" method="post" enctype="multipart/form-data" action="<?=View::escape($action)?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><input type="hidden" name="MAX_FILE_SIZE" value="20971520">
<section class="form-section"><div class="form-section-heading"><h2>Project identity</h2></div><div class="form-grid"><div class="form-field span-2"><label for="title">Project title *</label><input id="title" name="title" maxlength="300" required value="<?=View::escape($value('title'))?>"></div><div class="form-field"><label for="short_title">Short title</label><input id="short_title" name="short_title" maxlength="120" value="<?=View::escape($value('short_title'))?>"></div><div class="form-field"><label for="project_status">Project status</label><select id="project_status" name="project_status"><?php foreach(['planned','ongoing','completed','suspended','cancelled']as$status):?><option value="<?=$status?>"<?=$value('project_status')===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></div><div class="form-field"><label for="lead_department_id">Lead department *</label><select id="lead_department_id" name="lead_department_id" required><?php foreach($departments as$d):?><option value="<?=(int)$d['id']?>"<?=$value('lead_department_id')===(string)$d['id']?' selected':''?>><?=View::escape($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label for="lead_research_unit_id">Lead research unit</label><select id="lead_research_unit_id" name="lead_research_unit_id"><option value="">Department-level project</option><?php foreach($researchUnits as$unit):?><option value="<?=(int)$unit['id']?>"<?=$value('lead_research_unit_id')===(string)$unit['id']?' selected':''?>><?=View::escape($unit['name'])?></option><?php endforeach;?></select></div><div class="form-field span-2"><label for="slug">Public URL</label><input id="slug" name="slug" maxlength="320" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?=View::escape($value('slug'))?>"><p class="field-guidance">Leave blank to generate from the title.</p></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Timeline and funding</h2></div><div class="form-grid"><div class="form-field"><label for="start_date">Start date</label><input id="start_date" name="start_date" type="date" value="<?=View::escape($value('start_date'))?>"></div><div class="form-field"><label for="end_date">End date</label><input id="end_date" name="end_date" type="date" value="<?=View::escape($value('end_date'))?>"></div><div class="form-field"><label for="budget_amount">Budget amount</label><input id="budget_amount" name="budget_amount" type="number" min="0" step="0.01" value="<?=View::escape($value('budget_amount'))?>"></div><div class="form-field"><label for="currency_code">Currency</label><input id="currency_code" name="currency_code" maxlength="3" value="<?=View::escape($value('currency_code'))?>" placeholder="UGX"></div><div class="form-field"><label for="funding_reference">Funding reference</label><input id="funding_reference" name="funding_reference" maxlength="150" value="<?=View::escape($value('funding_reference'))?>"></div><div class="form-field"><label for="project_url">External project URL</label><input id="project_url" name="project_url" type="url" maxlength="500" value="<?=View::escape($value('project_url'))?>" placeholder="https://"></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Hero image</h2><p>Reuse an image URL from the media catalogue or upload a new project image.</p></div><div class="form-grid"><div class="form-field span-2"><label for="hero_media_id">Existing image</label><select id="hero_media_id" name="hero_media_id"><option value="">No image</option><?php foreach($images as$image):?><option value="<?=(int)$image['id']?>"<?=$value('hero_media_id')===(string)$image['id']?' selected':''?>><?=View::escape($image['original_name'])?></option><?php endforeach;?></select></div><div class="form-field span-2 upload-field"><label for="hero_image">Upload image</label><input id="hero_image" name="hero_image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><p class="field-guidance">JPEG, PNG, WebP, or GIF; maximum 20 MB.</p></div><div class="form-field span-2"><label for="hero_alt_text">Image description</label><input id="hero_alt_text" name="hero_alt_text" maxlength="255" value="<?=View::escape($value('hero_alt_text'))?>"><p class="field-guidance">Required for a new upload.</p></div></div></section>
<section class="form-section"><div class="form-section-heading"><h2>Public project content</h2><p>A summary is required before publication.</p></div><div class="form-grid"><?php foreach(['summary'=>'Summary','objectives'=>'Objectives','methodology'=>'Methodology','expected_outputs'=>'Expected outputs','outcomes'=>'Outcomes','impact'=>'Impact']as$field=>$label):?><div class="form-field span-2"><label for="<?=$field?>"><?=$label?><?=$field==='summary'?' * for publishing':''?></label><textarea id="<?=$field?>" name="<?=$field?>" rows="<?=$field==='summary'?5:7?>"><?=View::escape($value($field))?></textarea></div><?php endforeach;?></div></section><?php if($editing):?><section class="form-section"><div class="form-field"><label for="revision_note">Revision note</label><textarea id="revision_note" name="revision_note" rows="3"><?=View::escape($revisionNote)?></textarea></div></section><?php endif;?><div class="form-actions"><?php if($published):?><button class="button button-primary" type="submit" name="submit_action" value="save_live">Save published changes</button><?php else:?><button class="button <?=$canPublishDirectly?'button-secondary':'button-primary'?>" type="submit" name="submit_action" value="save"><?=$editing?'Save revision':'Create draft'?></button><?php if($canPublishDirectly):?><button class="button button-primary" type="submit" name="submit_action" value="publish"><?=$editing?'Save and publish':'Create and publish'?></button><?php endif;?><?php endif;?><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/projects<?=$editing?'/'.$projectId:''?>">Cancel</a></div></form>
